//! Independent Python JSON + big-endian framing + Foundry Keccak answers.
use super::protocol::*;
use alloy_primitives::{hex, keccak256, B256};

#[test]
fn signed_attestation_preimage_vectors() {
    {
        let result: Vec<TributeOfferResult> = serde_json::from_str(r#"[{"token_id":"0x6565656565656565656565656565656565656565656565656565656565656565","owner":"0x2222222222222222222222222222222222222222","issuance_amount_minor":"0x11","nominal_amount_minor":"0x12","effective_reference_price_minor":"0x13","su_hashes":["su-a"],"wallet_addresses":["wallet-b"],"sra_addresses":["sra-c"],"zk_expected_hashes":{"nft_hash":"0x6161616161616161616161616161616161616161616161616161616161616161","binding_hash":"0x6262626262626262626262626262626262626262626262626262626262626262"},"status":"Created"}]"#).unwrap();
        let actual = tribute_offer_attestation_preimage(B256::repeat_byte(0x11), &result).unwrap();
        assert_eq!(hex::encode(&actual), "");
        assert_eq!(
            hex::encode(keccak256(&actual)),
            "703d39f27d541bfb2043c7bd15c7b7f802563a9637dc2325b5cb8e74de5ed7b2"
        );
    }
    {
        let result: GratisOpResult = serde_json::from_str(r#"{"status":"Applied","new_balance":[33],"new_pledged":[34],"event_amount":"0x11","next_op_nonce":5,"fidelity":{"new_blob":[33],"qualified_start_initialized":123,"league":7},"inputs_canonical_hash":"0x1111111111111111111111111111111111111111111111111111111111111111","attestation_tag":[81,82],"encrypted_event_amount":[35]}"#).unwrap();
        let actual = gratis_op_attestation_preimage(B256::repeat_byte(0x11), &result).unwrap();
        assert_eq!(hex::encode(&actual), "");
        assert_eq!(
            hex::encode(keccak256(&actual)),
            "c712ea15201e08c9452b2fca321cbed2315754023a3ce667b46ceb4c6de64c92"
        );
    }
    {
        let result: PromisOpResult = serde_json::from_str(r#"{"status":"Applied","new_balance":[33],"event_amount":"0x11","next_op_nonce":5,"inputs_canonical_hash":"0x1111111111111111111111111111111111111111111111111111111111111111","attestation_tag":[81,82],"encrypted_event_amount":[35]}"#).unwrap();
        let actual = promis_op_attestation_preimage(B256::repeat_byte(0x11), &result).unwrap();
        assert_eq!(hex::encode(&actual), "");
        assert_eq!(
            hex::encode(keccak256(&actual)),
            "7e0bc5c10c3e70bd9a4d4b9b31c53ee8855d3fa39a91575c1ab5e82e6906bf17"
        );
    }
    {
        let result: FidelityCohortResult = serde_json::from_str(r#"{"outcome":{"new_blob":[33],"qualified_start_initialized":123,"league":7},"inputs_canonical_hash":"0x1111111111111111111111111111111111111111111111111111111111111111","attestation_tag":[81,82]}"#).unwrap();
        let actual =
            fidelity_cohort_attestation_preimage(B256::repeat_byte(0x11), &result).unwrap();
        assert_eq!(hex::encode(&actual), "");
        assert_eq!(
            hex::encode(keccak256(&actual)),
            "6ef0099eed8692c7d44bb73ea5764b46de28f087665551b9ef439b30515b8d91"
        );
    }
    {
        let result: Vec<FidelityLeagueEntry> = serde_json::from_str(
            r#"[{"owner":"0x2222222222222222222222222222222222222222","league":7,"rcfi":"0x11"}]"#,
        )
        .unwrap();
        let actual =
            fidelity_snapshot_attestation_preimage(B256::repeat_byte(0x11), &result).unwrap();
        assert_eq!(hex::encode(&actual), "");
        assert_eq!(
            hex::encode(keccak256(&actual)),
            "6b0597000ab7b67d60bd9f92af329cdc74b11beede63c58070426ef21a676049"
        );
    }
    {
        let result: FidelityQueryResult = serde_json::from_str(r#"{"rcfi":"0x11","efficiency":"0x12","league":7,"inputs_canonical_hash":"0x1111111111111111111111111111111111111111111111111111111111111111","attestation_tag":[81,82]}"#).unwrap();
        let actual = fidelity_query_attestation_preimage(B256::repeat_byte(0x11), &result).unwrap();
        assert_eq!(hex::encode(&actual), "");
        assert_eq!(
            hex::encode(keccak256(&actual)),
            "93fbc343fa62bf4967009e856b9ee3c17e5133575c7ff45f324452c81e958071"
        );
    }
}
